open(my $fh, '<', 'sequences.fasta') or die "Cannot open file: $!";
my %seqs;
my $current_name;
my $current_seq = "";

while(<$fh>) {
    chomp;
    if (/^>(\S+)/) {
        if ($current_name) {
            $seqs{$current_name} = $current_seq;
        }
        $current_name = $1;
